{
  "part": {
    "name": "Tapered clevis-to-hook link arm",
    "description": "Single solid link/lever with a forked clevis end (with two pin-boss ears and a central slot) transitioning into a long tapered arm body and terminating in a rounded hook/lug end with a concave notch and a rounded cap feature.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Largely symmetric about the mid-plane y=0 (mirrored left/right across the slot and side faces), with end features split into mirrored pairs where the clevis slot interrupts cylindrical surfaces."
  },
  "Section": [
    {
      "id": "S1",
      "name": "Clevis / forked mounting end",
      "features included": [
        "Forked clevis slot (U-shaped opening) at the end",
        "Two clevis ears (upper/lower in width direction) with aligned pin-bore surfaces",
        "Outer rounded end profile on each ear",
        "Slot-bottom/end stop face inside clevis"
      ],
      "function intent": "Provide a pinned mounting interface to a mating link/bracket while allowing rotation about the pin axis; transmit axial and bending loads from the pin into the arm body.",
      "physical behavior": "Pin loads generate bearing pressure on the pin-bore cylindrical surfaces; the two ears act as parallel shear/bending members around the slot, while the rounded outer profiles reduce stress concentration at the clevis end. Loads flow from the bore region into the arm via the ear bodies and into the tapered web.",
      "geometry": "End region split into two ears separated by a central slot; each ear has an outer cylindrical/rounded end surface (R7.5) and an interrupted pin-bore cylindrical surface (R3) due to the slot. The slot is bounded by two parallel planar inner walls and a planar end face (slot bottom) deeper into the part.",
      "location": "At negative X extreme (x approximately -75.75 to -60.75), spanning full thickness z=0..15 and overall width y approximately -8.19..+8.19 with a slot between y=-3.5 and y=+3.5.",
      "colour": {
        "R": 220,
        "G": 60,
        "B": 60
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Ear outer round (lower ear)",
          "Brep_id": "FACE 6",
          "description": "Outer cylindrical surface (R7.5, axis along Y) forming the rounded end profile of one clevis ear."
        },
        {
          "face_code": "0001",
          "name": "Ear outer round (upper ear)",
          "Brep_id": "FACE 15",
          "description": "Outer cylindrical surface (R7.5, axis along Y) forming the rounded end profile of the mirrored clevis ear."
        },
        {
          "face_code": "0002",
          "name": "Clevis slot inner wall (negative Y)",
          "Brep_id": "FACE 3",
          "description": "Planar wall at y=-3.5 defining one side of the clevis slot opening."
        },
        {
          "face_code": "0003",
          "name": "Clevis slot inner wall (positive Y)",
          "Brep_id": "FACE 4",
          "description": "Planar wall at y=+3.5 defining the opposite side of the clevis slot opening."
        },
        {
          "face_code": "0004",
          "name": "Pin-bore cylinder (upper ear segment)",
          "Brep_id": "FACE 0",
          "description": "Cylindrical bearing surface (R3, axis along Y) for the pin bore in one ear; surface is interrupted by the slot, so only the ear segment exists."
        },
        {
          "face_code": "0005",
          "name": "Pin-bore cylinder (lower ear segment)",
          "Brep_id": "FACE 1",
          "description": "Cylindrical bearing surface (R3, axis along Y) for the pin bore in the mirrored ear; interrupted by the slot."
        },
        {
          "face_code": "0006",
          "name": "Clevis slot end face (slot bottom/stop)",
          "Brep_id": "FACE 2",
          "description": "Planar face at x=-60.75 that closes/terminates the clevis slot depth."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S1",
          "target id": "S2",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S1",
          "target id": "S2",
          "function relationship": "constrains_dof",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "S2",
      "name": "Tapered arm web / main body",
      "features included": [
        "Long tapered prismatic web between end interfaces",
        "Opposed side faces with slight taper (in X-Y projection)",
        "Top and bottom planar faces with slight slope (in X-Z projection)"
      ],
      "function intent": "Provide the main load path between the clevis end and the hook end while minimizing mass via tapering; maintain stiffness and alignment between interfaces.",
      "physical behavior": "Acts primarily as a beam in tension/compression and bending. The taper reduces cross-section toward one end, concentrating compliance where needed while keeping adequate stiffness near higher-load interface regions. Side faces and top/bottom planes provide global stiffness and define the arm envelope for clearance.",
      "geometry": "Four dominant long planar faces forming a tapered prism: top plane, bottom plane, and two side planes (±Y). Planes are slightly angled relative to global axes, indicating taper and mild longitudinal slope.",
      "location": "Central span along X between clevis region (around x=-60.75) and hook end region (around x=~60..75). Extends full thickness z=0..15 and near-full width y up to about ±8.19 with taper.",
      "colour": {
        "R": 70,
        "G": 170,
        "B": 70
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Top face (tapered/slope plane)",
          "Brep_id": "FACE 5",
          "description": "Large planar top surface spanning most of the arm length; slightly tilted (normal has small +X component)."
        },
        {
          "face_code": "0008",
          "name": "Side face (positive Y)",
          "Brep_id": "FACE 16",
          "description": "Large planar side surface on +Y side; slightly angled due to width taper along X."
        },
        {
          "face_code": "0009",
          "name": "Bottom face (tapered/slope plane)",
          "Brep_id": "FACE 11",
          "description": "Large planar bottom surface spanning most of the arm; slightly tilted (normal has small +X component, opposite Z)."
        },
        {
          "face_code": "0010",
          "name": "Side face (negative Y)",
          "Brep_id": "FACE 9",
          "description": "Large planar side surface on -Y side; slightly angled due to width taper along X."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S2",
          "target id": "S1",
          "function relationship": "distributes_stress",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S2",
          "target id": "S3",
          "function relationship": "transmits_load",
          "structural relationship": "blends_into"
        },
        {
          "source id": "S2",
          "target id": "S3",
          "function relationship": "provides_clearance",
          "structural relationship": "adjacent_to"
        }
      ]
    },
    {
      "id": "S3",
      "name": "Hook / lug end interface",
      "features included": [
        "Outer rounded end (large-radius cylindrical end surface)",
        "Concave notch / hook seat (small-radius cylindrical surface)",
        "Small side relief faces around notch (y=±3 planes)",
        "Rounded cap/boss feature (cylinder with axis along Z)",
        "Local end/top planar face at z=15"
      ],
      "function intent": "Provide a receiving/engaging interface (hook/notch) for a mating pin/rod/edge and a robust end geometry for load introduction and retention; offer local clearance and contact surfaces for engagement.",
      "physical behavior": "Contact occurs on the concave notch cylinder, generating compressive contact stress and tangential friction; the outer rounded end reduces snagging and stress concentrations. The end cap/boss and top face provide additional bearing/stop surfaces and strengthen the end against bending and prying loads.",
      "geometry": "End region composed of a large outer cylindrical patch (R9, axis along Y), a smaller inner cylindrical notch (R3, axis along Y), a small additional cylindrical patch (R3, axis along Y) near the upper end, two small planar side faces at y=±3 that bound/relieve the notch area, a vertical-axis cylinder (R3, axis along Z) forming a rounded cap/side, and a planar top face at z=15 over part of the end.",
      "location": "At positive X extreme (x approximately 59.75 to 75.75), centered around y=0, spanning thickness z=0..15 with local shaping near the end.",
      "colour": {
        "R": 70,
        "G": 110,
        "B": 220
      },
      "major_faces": [
        {
          "face_code": "0011",
          "name": "Outer end round (main nose)",
          "Brep_id": "FACE 10",
          "description": "Large cylindrical surface (R9, axis along Y) forming the outer rounded end of the hook/lug region."
        },
        {
          "face_code": "0012",
          "name": "End top face",
          "Brep_id": "FACE 17",
          "description": "Planar face at z=15 covering the top of the end region (local plateau/closure)."
        },
        {
          "face_code": "0013",
          "name": "End cap side cylinder (vertical axis)",
          "Brep_id": "FACE 13",
          "description": "Cylindrical surface (R3, axis along Z) forming a rounded side/cap feature near the end."
        },
        {
          "face_code": "0014",
          "name": "Hook seat / concave notch cylinder",
          "Brep_id": "FACE 7",
          "description": "Concave cylindrical surface (R3, axis along Y) that forms the primary hook/notch contact seat."
        },
        {
          "face_code": "0015",
          "name": "Notch side relief face (negative Y)",
          "Brep_id": "FACE 12",
          "description": "Small planar face at y=-3 bounding the notch/relief opening on one side."
        },
        {
          "face_code": "0016",
          "name": "Notch side relief face (positive Y)",
          "Brep_id": "FACE 14",
          "description": "Small planar face at y=+3 bounding the notch/relief opening on the opposite side."
        },
        {
          "face_code": "0017",
          "name": "Upper small cylinder patch near end",
          "Brep_id": "FACE 8",
          "description": "Small cylindrical surface (R3, axis along Y) near the upper portion of the end shaping/transition."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S3",
          "target id": "S2",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S3",
          "target id": "S2",
          "function relationship": "locates_mating_part",
          "structural relationship": "adjacent_to"
        }
      ]
    }
  ]
}
